import type { Command } from "foldkit";
import { Ui } from "foldkit";

export const { Model } = Ui.Checkbox;
export type Model = Ui.Checkbox.Model;

export const { SetChecked } = Ui.Checkbox;
export const { Message } = Ui.Checkbox;
export type Toggled = Ui.Checkbox.Toggled;
export type SetChecked = Ui.Checkbox.SetChecked;
export type Message = Ui.Checkbox.Message;

export const { ToggledChecked } = Ui.Checkbox;
export const { OutMessage } = Ui.Checkbox;
export type ToggledChecked = Ui.Checkbox.ToggledChecked;
export type OutMessage = Ui.Checkbox.OutMessage;

export type InitConfig = Ui.Checkbox.InitConfig;
export type Commands = readonly Command.Command<Message>[];
export type InitReturn = readonly [Model, Commands];
export type UpdateReturn = ReturnType<typeof Ui.Checkbox.update>;

export type CheckboxAttributes = Ui.Checkbox.CheckboxAttributes;
export type ViewInputs = Ui.Checkbox.ViewInputs;

export const init = (config: InitConfig): InitReturn => [
  Ui.Checkbox.init(config),
  [],
];

export const { update } = Ui.Checkbox;
export const { setChecked } = Ui.Checkbox;
export const { reflectChecked } = Ui.Checkbox;
export const { view } = Ui.Checkbox;

export {
  baseUiCheckboxControlClassName,
  baseUiCheckboxDescriptionClassName,
  baseUiCheckboxLabelClassName,
  baseUiCheckboxRowClassName,
  baseUiCheckboxTextClassName,
} from "./view";

export const baseUiCheckboxRowClassName = "flex items-start gap-3";

export const baseUiCheckboxControlClassName =
  "flex h-5 w-5 shrink-0 items-center justify-center rounded border border-gray-400 bg-white text-sm leading-none text-gray-900 transition hover:bg-gray-50 focus:outline-none focus:ring-2 focus:ring-accent-500 focus:ring-offset-2 data-[checked]:border-gray-900 data-[checked]:bg-gray-900 data-[checked]:text-white data-[indeterminate]:border-gray-900 data-[indeterminate]:bg-gray-900 data-[indeterminate]:text-white data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

export const baseUiCheckboxLabelClassName =
  "text-sm font-medium leading-5 text-gray-900";

export const baseUiCheckboxDescriptionClassName =
  "text-sm leading-5 text-gray-500";

export const baseUiCheckboxTextClassName = "space-y-1";

import { Match as M, Schema as S } from "effect";
import { Command, Scene } from "foldkit";
import type { Html } from "foldkit/html";
import { html } from "foldkit/html";
import { m } from "foldkit/message";
import { evo } from "foldkit/struct";
import { describe, test } from "vitest";

import * as Checkbox from "./index";

const GotCheckboxMessage = m("GotCheckboxMessage", {
  message: Checkbox.Message,
});

const Model = S.Struct({
  checkbox: Checkbox.Model,
});

type Model = typeof Model.Type;

const Message = S.Union([GotCheckboxMessage]);
type Message = typeof Message.Type;

const initialModel: Model = {
  checkbox: Checkbox.init({ id: "terms-checkbox" })[0],
};

const update = (
  model: Model,
  message: Message
): readonly [Model, readonly Command.Command<Message>[]] =>
  M.value(message).pipe(
    M.withReturnType<readonly [Model, readonly Command.Command<Message>[]]>(),
    M.tagsExhaustive({
      GotCheckboxMessage: ({ message }) => {
        const [checkbox, checkboxCommands] = Checkbox.update(
          model.checkbox,
          message
        );

        return [
          evo(model, { checkbox: () => checkbox }),
          Command.mapMessages(checkboxCommands, (message) =>
            GotCheckboxMessage({ message })
          ),
        ];
      },
    })
  );

const view = (model: Model): Html => {
  const h = html<Message>();

  return h.submodel({
    slotId: model.checkbox.id,
    model: model.checkbox,
    view: Checkbox.view,
    viewInputs: {
      name: "terms",
      value: "accepted",
      toView: (attributes) =>
        h.div(
          [h.Class(Checkbox.baseUiCheckboxRowClassName)],
          [
            h.button(
              [
                ...attributes.checkbox,
                h.Class(Checkbox.baseUiCheckboxControlClassName),
              ],
              model.checkbox.isChecked ? ["✓"] : []
            ),
            h.input(attributes.hiddenInput),
            h.div(
              [h.Class(Checkbox.baseUiCheckboxTextClassName)],
              [
                h.label(
                  [
                    ...attributes.label,
                    h.Class(Checkbox.baseUiCheckboxLabelClassName),
                  ],
                  ["Accept terms"]
                ),
                h.p(
                  [
                    ...attributes.description,
                    h.Class(Checkbox.baseUiCheckboxDescriptionClassName),
                  ],
                  ["You agree to receive product updates."]
                ),
              ]
            ),
          ]
        ),
    },
    toParentMessage: (message) => GotCheckboxMessage({ message }),
  });
};

const disabledView = (model: Model): Html => {
  const h = html<Message>();

  return h.submodel({
    slotId: "disabled-checkbox",
    model: model.checkbox,
    view: Checkbox.view,
    viewInputs: {
      isDisabled: true,
      toView: (attributes) =>
        h.button(
          [
            ...attributes.checkbox,
            h.Class(Checkbox.baseUiCheckboxControlClassName),
          ],
          ["Disabled"]
        ),
    },
    toParentMessage: (message) => GotCheckboxMessage({ message }),
  });
};

describe("Base UI Checkbox registry view", () => {
  test("toggles checked state through the Foldkit primitive", () => {
    Scene.scene(
      { update, view },
      Scene.with(initialModel),
      Scene.expect(Scene.role("checkbox", { name: "Accept terms" })).toExist(),
      Scene.expect(Scene.role("checkbox", { name: "Accept terms" })).toHaveAttr(
        "aria-checked",
        "false"
      ),
      Scene.click(Scene.role("checkbox", { name: "Accept terms" })),
      Scene.expect(Scene.role("checkbox", { name: "Accept terms" })).toHaveAttr(
        "aria-checked",
        "true"
      )
    );
  });

  test("supports disabled state", () => {
    Scene.scene(
      { update, view: disabledView },
      Scene.with(initialModel),
      Scene.expect(Scene.role("checkbox", { name: "Disabled" })).toBeDisabled()
    );
  });
});
